    const intro=root?.firstElementChild;
    const statusBanner=make('div','hidden rounded border border-outline-variant bg-surface-container-low p-space-sm text-body-sm text-on-surface-variant','');
    if(intro)intro.insertAdjacentElement('afterend',statusBanner);
