      const renderDimensions=()=>{if(!dimensionList||!rowTemplate)return;dimensionList.replaceChildren();dimensions.forEach((d,i)=>{const row=rowTemplate.cloneNode(true);row.dataset.id=d.id;const checkbox=row.querySelector('input[type="checkbox"]');if(checkbox){checkbox.checked=d.selected!==false;checkbox.disabled=!writable;checkbox.addEventListener('change',()=>{d.selected=checkbox.checked;setFooter();});}const title=row.querySelector('.dim-title');if(title)title.textContent=d.name;const desc=row.querySelector('.dim-desc');if(desc)desc.textContent=d.description||'No description supplied.';const priority=row.querySelector('.dimension-row span.rounded');if(priority)priority.textContent=d.priority>=4?'High Priority':d.priority===3?'Medium Priority':'Exploratory';const actions=row.lastElementChild;if(actions){const edit=actions.querySelector('button[title="Edit Dimension"]');const remove=actions.querySelector('.btn-remove-dim');if(edit){edit.disabled=!writable;edit.addEventListener('click',()=>{const name=prompt('Edit dimension name',d.name);if(name===null)return;const description=prompt('Edit dimension description',d.description||'');if(description===null)return;d.name=name.trim()||d.name;d.description=description.trim();renderDimensions();});}if(remove){remove.disabled=!writable;remove.addEventListener('click',()=>{dimensions.splice(i,1);renderDimensions();});}}dimensionList.append(row);});setFooter();};
