    const stageState=(group,s)=>{const completed=new Set(s.stages_completed||[]);const allDone=['completed','partial'].includes(String(s.status).toLowerCase());const current=String(s.current_stage||'').toLowerCase();if(allDone||group.keys.every(k=>completed.has(k)))return'complete';if(String(s.status).toLowerCase()==='failed'&&(group.keys.includes(current)||(group.keys.includes('checklist')&&current==='failed'&&s.can_resume)))return'failed';if(group.keys.includes(current)||(group.label.startsWith('05.')&&current.includes('coverage and evidence')))return'active';return'pending';};
    const stageMessage=(group,state,s)=>{if(state==='active')return s.current_message||'Backend is processing this stage.';if(state==='failed')return s.errors?.[0]||s.current_message||'The backend reported that this stage failed.';if(state==='pending')return group.detail;const sourceCount=Number(s.sources_found??latestSources.length);const claimCount=Number(s.claims_extracted||0);if(!group.keys.length)return`FastAPI created session ${sessionId}.`;if(group.keys.includes('understanding'))return'FastAPI interpreted this session’s research goal.';if(group.keys.includes('dimensions'))return`FastAPI generated ${scopeData?.dimensions?.length||0} research dimensions for this session.`;if(group.keys.includes('scope_review'))return'Approved scope was saved before starting the pipeline.';if(group.keys.includes('query_planning'))return'Backend completed research query planning.';if(group.keys.includes('searching'))return`Web search completed and found ${sourceCount} source${sourceCount===1?'':'s'}.`;if(group.keys.includes('extracting')){const extracted=latestSources.filter(x=>String(x.extraction_status).toLowerCase()==='success').length;return`Source ingestion completed: ${extracted} of ${sourceCount} sources extracted successfully.`;}if(group.keys.includes('claims'))return`Claim extraction completed: ${claimCount} claims saved.`;if(group.keys.includes('coverage'))return'Coverage, evidence, conflict, and freshness analysis completed.';if(group.keys.includes('gaps'))return'Gap and conflict analysis completed and saved.';if(group.keys.includes('checklist'))return'Verification checklist generation completed.';return group.detail;};
    const timelineIcon=(state)=>{const ns='http://www.w3.org/2000/svg';const svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('class',state==='active'?'h-4 w-4 animate-spin': 'h-4 w-4');svg.setAttribute('aria-hidden','true');svg.setAttribute('focusable','false');const path=document.createElementNS(ns,'path');path.setAttribute('fill','none');path.setAttribute('stroke','currentColor');path.setAttribute('stroke-width','2');path.setAttribute('stroke-linecap','round');path.setAttribute('stroke-linejoin','round');if(state==='complete')path.setAttribute('d','M5 12.5 9.5 17 19 7.5');else if(state==='active'){path.setAttribute('d','M20 12a8 8 0 1 1-2.34-5.66');path.setAttribute('stroke-dasharray','12 8');}else if(state==='failed')path.setAttribute('d','M12 8v5m0 3h.01M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20Z');else path.setAttribute('d','M12 4a8 8 0 1 0 0 16 8 8 0 0 0 0-16Z');svg.append(path);return svg;};
